import sys, requests; sys.path.insert(0, "/home/claude/telas")
from comum import rotas, token
from playwright.sync_api import sync_playwright
B = "http://127.0.0.1:8900"; A = B + "/api"; ok = f = 0
def check(n, c, x=""):
    global ok, f
    if c: ok += 1; print("OK   ", n)
    else: f += 1; print("FALHA", n, x)
STUB = "window.Chart=function(){return{destroy(){},update(){},data:{datasets:[]}}};window.Chart.register=function(){};window.Chart.defaults={font:{},plugins:{legend:{labels:{}},tooltip:{}},scale:{grid:{}}};"
# ── dados: Rawtech (dono da plataforma pela configuração) e uma empresa cliente ──
for emp, nome, email, senha in [("Rawtech", "Wendell Xavier", "admin@rawtech.test", "nova-senha-adm"), ("Construtora Alfa", "Ana Lima", "ana@alfa.test", "senha-da-ana-1")]:
    requests.post(A+"/cadastro", json={"empresa": {"nome": emp, "cidade": "Recife", "uf": "PE"}, "admin": {"nome": nome, "email": email, "senha": senha}})
    requests.post(A+"/confirmar-email", json={"token": token(email, "confirmar")})
ana = requests.Session(); ana.post(A+"/entrar", json={"email": "ana@alfa.test", "senha": "senha-da-ana-1"})
for c, n in [("ALF-01", "Edifício Mar Azul"), ("ALF-02", "Galpão Norte")]: ana.post(A+"/projetos", json={"codigo": c, "nome": n})
requests.post(A+"/fale-conosco", json={"nome": "Maria Souza", "email": "maria@construtora.com.br", "assunto": "Comercial", "mensagem": "Somos uma construtora com 40 funcionários de campo. Gostaria de uma demonstração."})
ana.post(A+"/fale-conosco", json={"assunto": "Problema no sistema", "mensagem": "O cronograma não abre no celular do encarregado."})
requests.post(A+"/fale-conosco", json={"nome": "Pedro Rocha", "email": "pedro@eng.test", "assunto": "Dúvida", "mensagem": "O sistema emite o RDO em PDF para o cliente assinar?"})
erros = []
with sync_playwright() as p:
    nav = p.chromium.launch(executable_path="/usr/bin/google-chrome")
    pg = nav.new_page(viewport={"width": 1366, "height": 800}); rotas(pg)
    pg.route("**/chart.umd.min.js", lambda r: r.fulfill(body=STUB, content_type="application/javascript"))
    pg.on("pageerror", lambda e: erros.append(str(e)))
    pg.goto(B+"/painel.html"); pg.wait_for_url("**/entrar.html?voltar=painel"); check("Sem login: painel manda para o login", True)
    pg.fill("#e-email", "admin@rawtech.test"); pg.fill("#e-senha", "nova-senha-adm"); pg.click("#f-entrar button[type=submit]")
    pg.wait_for_url("**/painel.html"); pg.wait_for_selector("#conteudo:not([hidden])"); check("Depois do login volta ao painel", True)
    check("Contadores: 3 pendentes", pg.inner_text("#k-pend") == "3" and pg.inner_text("#cont-pend") == "3", pg.inner_text("#k-pend"))
    check("Lista com as 3 mensagens", pg.locator(".item").count() == 3)
    pg.click(".item >> text=Ana Lima"); pg.wait_for_selector(".dt-nome")
    check("Abre a mensagem com empresa e origem", "Ana Lima" in pg.inner_text(".dt-nome") and "Construtora Alfa" in pg.inner_text(".dt-de") and "Dentro do sistema" in pg.inner_text(".dt-cab"))
    href = pg.get_attribute(".dt-acoes a", "href"); check("Responder abre o e-mail preenchido", href.startswith("mailto:ana%40alfa.test?subject=") and "Task%20Flow" in href, href[:80])
    pg.fill("#dt-nota", "Liguei para a Ana, era o navegador antigo."); pg.click(".dt-nota .bt"); pg.wait_for_selector("#toast:not([hidden])")
    check("Salva a anotação interna", "Anotação salva" in pg.inner_text("#toast") and pg.locator(".it-nota").count() == 1)
    pg.click(".dt-acoes .bt-ok"); pg.wait_for_function("document.querySelector('#k-resp').textContent === '1'")
    check("Marca como respondida (contadores atualizam)", pg.inner_text("#k-pend") == "2")
    pg.select_option("#c-situacao", "pend"); check("Filtro Pendentes", pg.locator(".item").count() == 2)
    pg.select_option("#c-situacao", ""); pg.fill("#c-busca", "rdo"); check("Busca no texto da mensagem", pg.locator(".item").count() == 1 and "Pedro" in pg.inner_text(".item"))
    pg.fill("#c-busca", ""); pg.select_option("#c-origem", "login"); check("Filtro por origem", pg.locator(".item").count() == 2); pg.select_option("#c-origem", "")
    pg.click(".item >> text=Ana Lima"); pg.click(".dt-de .link"); pg.wait_for_selector("#aba-empresas:not([hidden])")
    check("Link da empresa abre a aba Empresas já filtrada", pg.locator("#e-corpo tr").count() == 1 and "Construtora Alfa" in pg.inner_text("#e-corpo"))
    pg.fill("#e-busca", ""); pg.dispatch_event("#e-busca", "input")
    check("Empresas: as 2 aparecem", pg.locator("#e-corpo tr").count() == 2 and pg.inner_text("#k-emp") == "2")
    linha = pg.locator("#e-corpo tr", has_text="Construtora Alfa")
    check("Números da empresa (2 obras, 1 usuário)", linha.locator("td").nth(3).inner_text() == "2" and linha.locator("td").nth(2).inner_text() == "1")
    check("Sua empresa marcada e sem botão de suspender", pg.locator("#e-corpo tr", has_text="sua empresa").locator(".td-acao button").count() == 0)
    linha.locator(".bt-perigo").click(); pg.wait_for_selector(".janela"); check("Pede confirmação antes de suspender", "desconectado" in pg.inner_text(".janela"))
    pg.click(".janela .bt-perigo"); pg.wait_for_function("document.querySelector('#k-susp').textContent === '1'")
    check("Empresa suspensa", "Suspensa" in linha.inner_text())
    check("Quem estava logado foi desconectado", ana.get(A+"/eu").status_code == 401)
    r = requests.post(A+"/entrar", json={"email": "ana@alfa.test", "senha": "senha-da-ana-1"}); check("Login da suspensa recebe aviso", r.status_code == 403 and "suspenso" in r.json()["erro"])
    linha.locator(".bt-ok").click(); pg.click(".janela .bt-pri"); pg.wait_for_function("document.querySelector('#k-susp').textContent === '0'")
    check("Reativa", requests.post(A+"/entrar", json={"email": "ana@alfa.test", "senha": "senha-da-ana-1"}).status_code == 200)
    pg.goto(B+"/index.html"); pg.wait_for_selector("#tf-contato")
    check("No sistema, o dono vê o botão Painel Mercurium", "Painel Mercurium" in pg.inner_text("#tf-contato") and pg.inner_text("#tf-badge") == "2")
    pg.click("#tf-contato"); pg.wait_for_url("**/painel.html"); check("Botão leva ao painel", True)
    pg.click("#bt-sair"); pg.wait_for_url("**/entrar.html"); check("Sair do painel", True)
    # cliente: não vê o painel e continua mandando Fale conosco pelo sistema
    c = nav.new_page(viewport={"width": 390, "height": 844}); rotas(c)
    c.route("**/chart.umd.min.js", lambda r: r.fulfill(body=STUB, content_type="application/javascript")); c.on("pageerror", lambda e: erros.append(str(e)))
    c.goto(B+"/entrar.html"); c.fill("#e-email", "ana@alfa.test"); c.fill("#e-senha", "senha-da-ana-1"); c.click("#f-entrar button[type=submit]"); c.wait_for_url("**/index.html")
    c.wait_for_selector("#tf-rodape-contato", state="attached"); check("Cliente: Fale conosco saiu do topo e ficou no rodapé", c.locator("#tf-contato").count() == 0)
    c.locator("#tf-rodape-contato").scroll_into_view_if_needed(); c.click("#tf-rodape-contato"); c.wait_for_selector("#tf-k-msg"); check("Cliente: o link do rodapé abre o mesmo Fale conosco", "ana@alfa.test" in c.inner_text(".tf-imp"))
    c.fill("#tf-k-msg", "Obrigada pelo retorno, resolvido."); c.click(".tf-imp [type=submit]"); c.wait_for_selector(".tf-imp", state="detached")
    c.goto(B+"/painel.html"); c.wait_for_selector("#negado:not([hidden])"); check("Cliente não entra no painel", c.locator("#conteudo").is_hidden())
    # celular, como dono
    m = nav.new_context(viewport={"width": 390, "height": 844}, is_mobile=True, has_touch=True).new_page(); rotas(m); m.on("pageerror", lambda e: erros.append(str(e)))
    m.goto(B+"/entrar.html?voltar=painel"); m.fill("#e-email", "admin@rawtech.test"); m.fill("#e-senha", "nova-senha-adm"); m.click("#f-entrar button[type=submit]")
    m.wait_for_selector("#conteudo:not([hidden])")
    larg = lambda: m.evaluate("document.documentElement.scrollWidth")
    check("Celular: Fale conosco sem rolagem lateral", larg() <= 390, larg())
    check("Celular: mensagem nova chegou (4 no total)", m.locator(".item").count() == 4)
    m.click(".item >> nth=0"); check("Celular: abre a leitura e esconde a lista", m.locator(".detalhe").is_visible() and m.locator(".lista").is_hidden())
    m.click(".dt-voltar"); check("Celular: volta à lista", m.locator(".lista").is_visible())
    m.click("[data-aba=empresas]"); check("Celular: Empresas em cartões sem rolagem lateral", larg() <= 390 and m.locator("#e-corpo tr").count() == 2, larg())
    nav.close()
check("Sem erros de JavaScript", not erros, erros)
print(f"RESULTADO: {ok} ok, {f} falhas")
